questionvariables.text:
/* Enumerate admissible (b, c, p, gap). q = p + gap, gap in {1,2,3}. */ cands : sublist( create_list([bb0, cc0, pp0, gg0], bb0,-3,3, cc0,-3,3, pp0,-3,3, gg0,1,3), lambda([z], block( [b:z[1], c:z[2], p:z[3], q:z[3]+z[4], fp, fq, aroc, wnum, wsign, wavg, wrecip], fp : p*p + b*p + c, fq : q*q + b*q + c, aroc : (fq - fp)/(q - p), /* = p + q + b, an integer */ wnum : fq - fp, /* forgot to divide by (q-p) */ wsign : -aroc, /* sign slip */ wavg : (fp + fq)/2, /* averaged the outputs */ wrecip : if aroc = 0 then 10^6 else 1/aroc, /* inverted ratio: run over rise = 1/AROC (guard div-by-zero) */ is( abs(fp) <= 18 and abs(fq) <= 18 and aroc # 0 and aroc # wnum and aroc # wsign and aroc # wavg and aroc # wrecip and wnum # wsign and wnum # wavg and wnum # wrecip and wsign # wavg and wsign # wrecip and wavg # wrecip ) )));
/* The wsign # aroc clause above already forces AROC # 0 (since wsign = -aroc), so every candidate has a genuinely sloping secant. Pick one at random. */ pick : rand(cands);
bb : pick[1]; cc : pick[2]; pp : pick[3]; qq : pick[3] + pick[4];
fx : x^2 + bb*x + cc; /* f(x), for display */ fp : pp^2 + bb*pp + cc; /* f(p) */ fq : qq^2 + bb*qq + cc; /* f(q) */
ta1 : (fq - fp)/(qq - pp); /* model answer: the AROC (an integer) */
wrong_num : fq - fp; /* forgot to divide by (q - p) */ wrong_sign : -ta1; /* (f(p)-f(q))/(q-p): sign slip */ wrong_avg : (fp + fq)/2; /* averaged f(p) and f(q) */ wrong_recip : 1/ta1; /* inverted the ratio: run over rise = 1/AROC */
